package com.clinic.appointment.repository;
import com.clinic.appointment.domain.SlotReservation;import jakarta.persistence.LockModeType;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.*;import java.util.*;
public interface SlotReservationRepository extends JpaRepository<SlotReservation,UUID>{
 @Modifying @Query(value="INSERT INTO slot_reservations(id,doctor_id,start_at,patient_id,hold_token,expires_at,confirmed,version) VALUES(:id,:doctor,:start,:patient,:token,:expires,false,0) ON CONFLICT (doctor_id,start_at) DO NOTHING",nativeQuery=true)int tryInsert(@Param("id")UUID id,@Param("doctor")UUID doctor,@Param("start")OffsetDateTime start,@Param("patient")UUID patient,@Param("token")UUID token,@Param("expires")Instant expires);
 @Lock(LockModeType.PESSIMISTIC_WRITE)Optional<SlotReservation> findByHoldToken(UUID token);void deleteByAppointmentId(UUID appointmentId);@Modifying @Query("delete from SlotReservation s where s.confirmed=false and s.expiresAt<:now")int deleteExpired(@Param("now")Instant now);@Query("select s.startAt from SlotReservation s where s.doctorId=:doctor and s.startAt>=:from and s.startAt<:to and (s.confirmed=true or s.expiresAt>:now)")List<OffsetDateTime> occupied(@Param("doctor")UUID doctor,@Param("from")OffsetDateTime from,@Param("to")OffsetDateTime to,@Param("now")Instant now);
}
